update public.content_variants set body = $json${"type":"true_false","answer":false,"question":"Because prices can rise quickly, crypto is a surefire way to get rich quickly.","difficulty":"beginner","explanation":"Crypto prices can rise and fall drastically. There is no guarantee of profit, and many people actually lose because of FOMO."}$json$::jsonb, body_id = $json${"type":"true_false","answer":false,"question":"Karena harganya bisa naik cepat, kripto adalah cara pasti untuk cepat kaya.","difficulty":"beginner","explanation":"Harga kripto bisa naik dan turun drastis. Tidak ada jaminan keuntungan, dan banyak orang justru rugi karena FOMO."}$json$::jsonb where id = '859bfcb7-36af-459c-a593-6ee8c758d5d3';
update public.content_variants set body = $json${"type":"true_false","answer":false,"question":"Good debts don't need to be repaid because they make money.","difficulty":"beginner","explanation":"All debts must be paid off according to schedule. What differentiates good debt is its productive purpose, not the obligation to pay it."}$json$::jsonb, body_id = $json${"type":"true_false","answer":false,"question":"Utang baik tidak perlu dilunasi karena menghasilkan uang.","difficulty":"beginner","explanation":"Semua utang harus dilunasi sesuai jadwal. Yang membedakan utang baik adalah tujuannya yang produktif, bukan kewajiban membayarnya."}$json$::jsonb where id = '899b8f11-b312-4a83-b9af-32f0e91fa934';
update public.content_variants set body = $json${"type":"multiple_choice","answer":"Money market mutual funds for 3 year purposes","options":["Money market mutual funds for 3 year purposes","Buying viral coins hopes for quick profits","Bet on prediction apps","Borrowing money for trading"],"question":"Which is closest to productive investment?","difficulty":"beginner","explanation":"Money market mutual funds have assets that earn interest and are suitable for medium-term goals."}$json$::jsonb, body_id = $json${"type":"multiple_choice","answer":"Reksa dana pasar uang untuk tujuan 3 tahun","options":["Reksa dana pasar uang untuk tujuan 3 tahun","Membeli koin viral berharap untung cepat","Bertaruh di aplikasi prediksi","Meminjam uang untuk trading"],"question":"Manakah yang paling mendekati investasi produktif?","difficulty":"beginner","explanation":"Reksa dana pasar uang memiliki aset yang menghasilkan bunga dan cocok untuk tujuan jangka menengah."}$json$::jsonb where id = '8c3d9c44-210d-4054-8b00-706bfa26120a';
update public.content_variants set body = $json${"type":"fill_blank","answer":"cost","question":"PayLater makes spending feel easy because it hides the true _____.","difficulty":"beginner","explanation":"Small installments make goods appear cheap, even though the total that must be paid could be greater."}$json$::jsonb, body_id = $json${"type":"fill_blank","answer":"biaya","question":"PayLater membuat pengeluaran terasa mudah karena menyembunyikan _____ sebenarnya.","difficulty":"beginner","explanation":"Cicilan kecil membuat barang tampak murah, padahal total yang harus dibayar bisa lebih besar."}$json$::jsonb where id = '8ce78f2d-57fe-4a3d-b78b-4dd35af9086b';
update public.content_variants set body = $json${"text":"Rina sold her crypto for a profit of IDR 500,000. He records the purchase date, purchase price, selling price and costs so he can report them according to applicable tax regulations."}$json$::jsonb, body_id = $json${"text":"Rina menjual kriptonya dengan keuntungan Rp 500.000. Ia mencatat tanggal beli, harga beli, harga jual, dan biaya agar bisa melaporkannya sesuai aturan pajak yang berlaku."}$json$::jsonb where id = '8d394cf1-151c-4579-aae8-8e4de3640489';
update public.content_variants set body = $json${"text":"An application claims to be able to double crypto money every month. Budi remembers this lesson: if returns are guaranteed, it is not an investment but a fraud. He closed the application."}$json$::jsonb, body_id = $json${"text":"Sebuah aplikasi mengklaim bisa menggandakan uang kripto setiap bulan. Budi ingat pelajaran ini: jika imbal hasil dijamin, itu bukan investasi melainkan penipuan. Ia menutup aplikasi tersebut."}$json$::jsonb where id = '8dc96832-80a4-48a2-b9da-90e8824dece5';
update public.content_variants set body = $json${"type":"multiple_choice","answer":"Daily transactions and saving money","options":["Long term investment","Daily transactions and saving money","Get high interest","Buying property"],"question":"What is the main function of a savings account?","difficulty":"beginner","explanation":"Savings accounts are designed for daily transactions such as paying for shopping, transfers and cash withdrawals, as well as saving money with easy access."}$json$::jsonb, body_id = $json${"type":"multiple_choice","answer":"Transaksi harian dan menyimpan uang","options":["Investasi jangka panjang","Transaksi harian dan menyimpan uang","Mendapat bunga tinggi","Membeli properti"],"question":"Apa fungsi utama rekening tabungan?","difficulty":"beginner","explanation":"Rekening tabungan dirancang untuk transaksi sehari-hari seperti bayar belanja, transfer, dan tarik tunai, serta menyimpan uang dengan akses mudah."}$json$::jsonb where id = '9104b858-9df6-4deb-977e-6916adcb0adc';
update public.content_variants set body = $json${"type":"true_false","answer":true,"question":"A mixed mutual fund that holds stocks and bonds is an example of a productive investment.","difficulty":"beginner","explanation":"Mutual funds have assets that generate profits and interest, so they are productive investments."}$json$::jsonb, body_id = $json${"type":"true_false","answer":true,"question":"Reksa dana campuran yang memiliki saham dan obligasi adalah contoh investasi produktif.","difficulty":"beginner","explanation":"Reksa dana memiliki aset yang menghasilkan keuntungan dan bunga, sehingga termasuk investasi produktif."}$json$::jsonb where id = '96adfa01-5655-4168-8a68-6218e8db9e0b';
update public.content_variants set body = $json${"text":"Doni was asked to invite three friends to get a crypto bonus. He remembered the characteristics of MLM and pyramids, then refused. The big bonus of recruiting people is a sign of fraud."}$json$::jsonb, body_id = $json${"text":"Doni diminta mengajak tiga teman untuk mendapatkan bonus kripto. Ia ingat ciri MLM dan piramida, lalu menolak. Bonus besar dari merekrut orang adalah tanda penipuan."}$json$::jsonb where id = '97c65f57-e797-48fe-9237-e8d9ac14c395';
update public.content_variants set body = $json${"type":"multiple_choice","answer":"The remaining balance is subject to interest and can grow larger","options":["The remaining balance is subject to interest and can grow larger","The bill was paid immediately","There are no additional fees","PayLater limit closes automatically"],"question":"What happens if you only pay the minimum on PayLater?","difficulty":"beginner","explanation":"Paying the minimum lets the interest work on the remaining bill, so the debt grows."}$json$::jsonb, body_id = $json${"type":"multiple_choice","answer":"Sisa tagihan dikenakan bunga dan bisa bertambah besar","options":["Sisa tagihan dikenakan bunga dan bisa bertambah besar","Tagihan langsung lunas","Tidak ada biaya tambahan","Limit PayLater tertutup otomatis"],"question":"Apa yang terjadi jika kamu hanya membayar minimum pada PayLater?","difficulty":"beginner","explanation":"Membayar minimum membiarkan bunga bekerja pada sisa tagihan, sehingga utang tumbuh."}$json$::jsonb where id = '999e7260-c68a-4230-9857-7814ef1ee6dc';

